    out, total = [], 0
    for n in nums:
        total += n
        out.append(total)
    return out

def letter_counts(word: str) -> Dict[str, int]:
    counts = {}
    for c in word:
        counts[c] = counts.get(c, 0) + 1
    return counts

def flatten(nested: list) -> List[int]:
    out = []
    for x in nested:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def sum_valid(items: List[str]) -> int:
    total = 0
    for s in items:
        try:
            total += int(s)
        except ValueError:
            pass
    return total

problems.desc:
Write a class `Stack` with:

- `push(x)`: add `x` to the top;
- `pop()`: remove and return the top item, or `None` if it's empty;
- `size()`: return how many items it holds.

problems.starter:
class Stack:
    def __init__(self):
        pass

    def push(self, x: int) -> None:
        pass

    def pop(self):
        pass

    def size(self) -> int:
        pass

problems.solution:
class Stack:
    def __init__(self):
        self.items = []

    def push(self, x: int) -> None:
        self.items.append(x)

    def pop(self):
        return self.items.pop() if self.items else None

    def size(self) -> int:
        return len(self.items)

def top_words(text: str, k: int) -> List[str]:
    counts = Counter(text.split())
    return sorted(counts, key=lambda w: (-counts[w], w))[:k]

def first_unique(s: str) -> int:
    counts = Counter(s)
    for i, c in enumerate(s):
        if counts[c] == 1:
            return i
    return -1

def merge(a: List[int], b: List[int]) -> List[int]:
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]

def count_subarrays(nums: List[int], k: int) -> int:
    seen = {0: 1}
    total = count = 0
    for n in nums:
        total += n
        count += seen.get(total - k, 0)
        seen[total] = seen.get(total, 0) + 1
    return count

def days_until_warmer(temps: List[int]) -> List[int]:
    answer = [0] * len(temps)
    stack = []
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            j = stack.pop()
            answer[j] = i - j
        stack.append(i)
    return answer

def count_paths(grid: List[List[int]]) -> int:
    cols = len(grid[0])
    row = [0] * cols
    row[0] = 1
    for r in grid:
        for c in range(cols):
            if r[c] == 1:
                row[c] = 0
            elif c > 0:
                row[c] += row[c - 1]
    return row[-1]

def trapped_water(heights: List[int]) -> int:
    lo, hi = 0, len(heights) - 1
    left_max = right_max = water = 0
    while lo < hi:
        if heights[lo] < heights[hi]:
            left_max = max(left_max, heights[lo])
            water += left_max - heights[lo]
            lo += 1
        else:
            right_max = max(right_max, heights[hi])
            water += right_max - heights[hi]
            hi -= 1
    return water
